"""Author-written solutions for the 2023 edition, printed page 219."""
from fractions import Fraction as F
from math import sqrt
from build_area_lessons import card, drawing, edges, mid, step


def coordinates(a,b,t):
    return tuple(x+t*(y-x) for x,y in zip(a,b))


def foot(p,a,b):
    v=(b[0]-a[0],b[1]-a[1])
    t=((p[0]-a[0])*v[0]+(p[1]-a[1])*v[1])/(v[0]**2+v[1]**2)
    return coordinates(a,b,t)


def views(points,base,*layers):
    return [drawing(points,base+list(lines),faces) for lines,faces in layers]


def fit_visible(item):
    """Center each construction phase, including complete circles, at the default zoom."""
    model=item['model']
    for i,view in enumerate(model['views'].values()):
        ids=set(view['points'])
        for key in ['segments','dashSegments','polygons']:
            for row in view.get(key,[]):ids.update(row)
        for circle in view.get('circles',[]):ids.update(circle.values())
        coords=[model['points'][k][:2] for k in ids]
        for circle in view.get('circles',[]):
            cx,cy,_=model['points'][circle['center']]
            px,py,_=model['points'][circle['through']]
            r=((cx-px)**2+(cy-py)**2)**.5
            coords.extend([(cx-r,cy-r),(cx+r,cy+r)])
        xs,ys=zip(*coords)
        width=max(xs)-min(xs);height=max(ys)-min(ys)
        scale=min(76/width if width else 1e9,52/height if height else 1e9)
        cx=(max(xs)+min(xs))/2;cy=(max(ys)+min(ys))/2
        for k,point in model['points'].items():
            if k.endswith(f'__v{i}'):
                point[0]=50+(point[0]-cx)*scale
                point[1]=35+(point[1]-cy)*scale


def make(n,statement,result,guidance,stages,pictures,practice,chapter=8):
    lesson=card(n,statement,result,[step(*item) for item in stages],pictures,guidance)
    lesson.update(printedPages=[219],pdfPages=[220],relatedChapter=chapter,practice=practice)
    return lesson


